const profile = $('Split for Enrich').item.json;
const profiles = $('Search Social Profiles').item.json;
const activities = $('Search Activities & Content').item.json;

// Helper: 提取第一个匹配的 URL
const findFirst = (results, pattern) => {
  if (!results || !results.organic) return null;
  for (const item of results.organic) {
    if (item.link && item.link.match(pattern)) {
      return { url: item.link, snippet: item.snippet || null };
    }
  }
  return null;
};

// 1. 提取社交平台链接（取第一个匹配）
const linkedin = findFirst(profiles, /linkedin\.com\/in\//);
const twitter = findFirst(profiles, /(twitter\.com|x\.com)\/(?!i\/)(?!search)(?!home)\w+/);
const github = findFirst(profiles, /github\.com\/(?!topics\/)[\w-]+(?:\/|$)/);
const blog = findFirst(profiles, /(medium\.com|substack\.com)/);

// 社交平台域名，用于过滤 enrichment_data
const socialDomains = /linkedin\.com|twitter\.com|x\.com|github\.com/;

// 2. 构建 enrichment_data 数组（排除社交主链接和社交平台 URL）
const enrichment_data = [];
const seenUrls = new Set();

const addItem = (item, type) => {
  if (!item.link || seenUrls.has(item.link)) return;
  if (socialDomains.test(item.link)) return; // 排除所有社交平台链接
  seenUrls.add(item.link);
  enrichment_data.push({
    type,
    title: item.title,
    url: item.link,
    snippet: item.snippet || null,
    position: item.position || null
  });
};

// 从 profiles 中添加其他链接（非社交平台）
if (profiles && profiles.organic) {
  profiles.organic.forEach(item => addItem(item, 'digital'));
}

// 从 activities 中添加活动/内容
if (activities && activities.organic) {
  activities.organic.forEach(item => {
    const isEvent = /speaker|conference|podcast|talk|panel|summit|webinar/i.test(item.title + ' ' + (item.snippet || ''));
    addItem(item, isEvent ? 'event' : 'content');
  });
}

// SQL escape 函数
const sq = (v) => (v && typeof v === 'string') ? v.replace(/'/g, "''") : '';
const sqj = (v) => {
  try {
    const s = typeof v === 'string' ? v : JSON.stringify(v || []);
    return s.replace(/'/g, "''");
  } catch(e) {
    return '[]';
  }
};

return [{
  json: {
    id: profile.id,
    linkedin_url: sq(linkedin?.url || profile.linkedin_url || ''),
    linkedin_snippet: sq(linkedin?.snippet || ''),
    twitter_url: sq(twitter?.url || ''),
    github_url: sq(github?.url || ''),
    blog_url: sq(blog?.url || ''),
    enrichment_data: sqj(enrichment_data)
  }
}];
